ADDITIONS = {'experiments/day17_parallel_static_worker.py': '"""Isolated worktree execution of the unchanged frozen static-tuning protocol.\n\nShares the GPU with diagnostics; timing is descriptive, not a compute benchmark.\nPublishes only to a branch of the existing mitosis-interference repository.\n"""\nfrom datetime import datetime, timezone\nimport fcntl\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\n\n\nROOT = Path(\'/workspace/mitosis-static-tuning\')\nBRANCH = \'day17-static-tuning-20261006\'\nRATES = [2e-5, 5e-5, 1e-4, 2e-4, 4e-4, 8e-4]\nLAUNCH_CUTOFF = datetime.fromisoformat(\'2026-10-07T03:00:00+00:00\')\nDEADLINE = \'2026-10-07T03:15:00+00:00\'\nSTATUS = Path(\'notes/day17_static_tuning_execution.json\')\nENV = os.environ.copy()\nENV.update(OMP_NUM_THREADS=\'8\', TOKENIZERS_PARALLELISM=\'false\',\n           GIT_TERMINAL_PROMPT=\'0\', GH_PROMPT_DISABLED=\'1\')\n\n\ndef now():\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef write(path, data):\n    p = Path(path)\n    temporary = p.with_suffix(p.suffix + \'.tmp\')\n    temporary.write_text(json.dumps(data, indent=2) + \'\\n\')\n    temporary.replace(p)\n\n\ndef read(args):\n    return subprocess.check_output(args, env=ENV, text=True, timeout=90).strip()\n\n\ndef command(args, log=None):\n    print(\'RUN\', \' \'.join(args), flush=True)\n    return subprocess.run(args, env=ENV, stdin=subprocess.DEVNULL, stdout=log,\n                          stderr=subprocess.STDOUT if log else None).returncode\n\n\ndef checkpoint_manifest():\n    manifest = {}\n    for folder in sorted(Path(\'results\').glob(\'day17_*\')):\n        if not folder.is_dir():\n            continue\n        for p in sorted((folder / \'checkpoint\').rglob(\'*\')):\n            if p.is_file():\n                digest = hashlib.sha256()\n                with p.open(\'rb\') as stream:\n                    for block in iter(lambda: stream.read(8 * 1024 * 1024), b\'\'):\n                        digest.update(block)\n                manifest[str(p)] = {\'bytes\': p.stat().st_size, \'sha256\': digest.hexdigest()}\n    return manifest\n\n\ndef preserve():\n    write(\'results/day17_checkpoint_preservation_manifest.json\', checkpoint_manifest())\n    if command([\'git\', \'add\', \'-A\']):\n        raise RuntimeError(\'Staging failed\')\n    if read([\'git\', \'status\', \'--porcelain\']):\n        if command([\'git\', \'commit\', \'-m\', \'Preserve isolated pilot-selected static baseline progress\']):\n            raise RuntimeError(\'Progress commit failed\')\n    if command([\'git\', \'push\', \'origin\', BRANCH]):\n        raise RuntimeError(\'Progress push failed; preserve local state\')\n    head = read([\'git\', \'rev-parse\', \'HEAD\'])\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + BRANCH]).split()[0] == head\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    print(\'STATIC_BASELINE_PROGRESS_PUSHED\', head, flush=True)\n\n\ndef verify_new_checkpoint_roundtrip():\n    # This worktree intentionally retains pointers for unrelated old checkpoints.\n    # Verify newly generated Day-17 checkpoints; do not replace the main manifest.\n    snapshot = read([\'git\', \'rev-parse\', \'HEAD\'])\n    manifest = json.loads(Path(\'results/day17_checkpoint_preservation_manifest.json\').read_text())\n    lines = read([\'git\', \'lfs\', \'ls-files\', \'--long\']).splitlines()\n    by_path = {line.split(\' \', 2)[2]: line.split()[0] for line in lines}\n    tensors = {p for p in manifest if Path(p).suffix in {\'.pt\', \'.safetensors\'}}\n    assert tensors <= set(by_path)\n    for p, item in manifest.items():\n        assert Path(p).stat().st_size == item[\'bytes\']\n        assert hashlib.sha256(Path(p).read_bytes()).hexdigest() == item[\'sha256\']\n        if p in tensors:\n            assert item[\'sha256\'] == by_path[p]\n    fresh = Path(\'/workspace\') / (\'mitosis-day17-lfs-verify-\' + datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%SZ\'))\n    assert not fresh.exists()\n    if command([\'git\', \'-c\', \'lfs.storage=\' + str(fresh), \'lfs\', \'fetch\',\n                \'--include=results/day17_*/checkpoint/**\', \'--exclude=\', \'origin\', BRANCH]):\n        raise RuntimeError(\'Fresh static checkpoint download failed\')\n    oids = {by_path[p] for p in tensors}\n    for oid in oids:\n        p = fresh / \'objects\' / oid[:2] / oid[2:4] / oid\n        assert p.is_file(), \'Missing remotely downloaded static checkpoint\'\n        assert hashlib.sha256(p.read_bytes()).hexdigest() == oid\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + BRANCH]).split()[0] == snapshot\n    receipt = {\'repository\': \'anitusiruk/mitosis-interference\', \'branch\': BRANCH,\n        \'preserved_snapshot_commit\': snapshot, \'verified_utc\': now(),\n        \'scope\': \'new Day-17 checkpoints only; unrelated checkpoints retain their main-branch receipts\',\n        \'all_day17_lfs_sha256_verified\': True, \'fresh_remote_lfs_fetch_returncode\': 0,\n        \'checkpoint_files\': len(manifest), \'tensor_files\': len(tensors),\n        \'unique_lfs_objects_verified\': len(oids),\n        \'checkpoint_bytes\': sum(r[\'bytes\'] for r in manifest.values())}\n    write(\'notes/day17_github_save_verification.json\', receipt)\n    print(\'STATIC_REMOTE_CHECKPOINT_ROUNDTRIP_PASS\', len(oids), flush=True)\n    return receipt\n\n\ndef run_job(records, name, rank, rate, seed, order, phase):\n    folder = Path(\'results\', name)\n    assert not folder.exists(), \'Refusing to overwrite \' + str(folder)\n    args = [sys.executable, \'-u\', \'-m\', \'experiments.day17_static_tuning\', \'--rank\', str(rank),\n            \'--learning-rate\', str(rate), \'--seed\', str(seed), \'--order\', order,\n            \'--output\', str(folder), \'--deadline-utc\', DEADLINE]\n    row = {\'name\': name, \'phase\': phase, \'status\': \'running\', \'started_utc\': now(), \'command\': args}\n    records.append(row)\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 44, \'github_save_pending\': True})\n    with Path(\'logs\', name + \'.txt\').open(\'x\') as log:\n        code = command(args, log)\n    row.update(status=\'completed\' if code == 0 else \'failed\', returncode=code, finished_utc=now())\n    if phase == \'replay_gate\' and code == 0:\n        with Path(\'logs\', name + \'_verify.txt\').open(\'x\') as log:\n            code = command([sys.executable, \'-u\', \'-m\', \'experiments.day17_static_replay_gate\',\n                            \'--output\', str(folder)], log)\n        row.update(replay_verification_returncode=code, status=\'completed\' if code == 0 else \'failed\')\n    if phase != \'replay_gate\':\n        with Path(\'logs\', name + \'_report.txt\').open(\'x\') as log:\n            report_code = command([sys.executable, \'-u\', \'-m\', \'experiments.day17_static_tuning_report\'], log)\n        if report_code:\n            row[\'report_failed\'] = True\n            code = report_code\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 44, \'github_save_pending\': True})\n    preserve()\n    print(\'STATIC_BASELINE_JOB\', name, row[\'status\'], flush=True)\n    if code:\n        raise RuntimeError(\'Baseline discrepancy preserved: \' + name)\n\n\ndef main():\n    os.chdir(ROOT)\n    ENV[\'MITOSIS_MODEL_REVISION\'] = json.loads(Path(\'notes/restart_20261006_preflight.json\').read_text())[\'backbone_revision\']\n    lock = open(\'/workspace/mitosis-static-tuning-worker.lock\', \'a\')\n    fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\n    assert read([\'git\', \'branch\', \'--show-current\']) == BRANCH\n    assert read([\'git\', \'remote\', \'get-url\', \'origin\']) == \'https://github.com/anitusiruk/mitosis-interference.git\'\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    assert not STATUS.exists(), \'An existing preserved attempt requires inspection\'\n    records, failed, stopped = [], False, False\n    try:\n        if datetime.now(timezone.utc) >= LAUNCH_CUTOFF:\n            stopped = True\n        else:\n            run_job(records, \'day17_rank96_reference_replay\', 96, 2e-4, 2031, \'b_first\', \'replay_gate\')\n        for rank in [8, 96]:\n            for rate in RATES:\n                for order in [\'canonical\', \'b_first\']:\n                    if stopped or datetime.now(timezone.utc) >= LAUNCH_CUTOFF:\n                        stopped = True\n                        break\n                    tag = int(round(rate * 1e6))\n                    run_job(records, f\'day17_pilot_rank{rank}_lr{tag}_seed2026_{order}\',\n                            rank, rate, 2026, order, \'pilot\')\n        pilots = [r for r in records if r[\'phase\'] == \'pilot\' and r[\'status\'] == \'completed\']\n        if len(pilots) == 24:\n            from experiments.day17_static_tuning_report import pilot_table, select_pilot_rates\n            data = pilot_table()\n            selected, grid = select_pilot_rates(data)\n            receipt = {\'selected_rates\': selected, \'grid_summary\': grid, \'selected_utc\': now(),\n                \'pilot_seed\': 2026, \'selection_metric\': \'final concept-macro accuracy, averaged paired pilot orders\',\n                \'tie_break\': \'smaller learning rate\', \'confirmation_outcomes_used\': False,\n                \'spec_sha256\': hashlib.sha256(Path(\'notes/day17_static_tuning_spec.md\').read_bytes()).hexdigest(),\n                \'pilot_grid_sha256\': hashlib.sha256(Path(\'results/day17_static_pilot_grid.csv\').read_bytes()).hexdigest()}\n            assert not Path(\'notes/day17_static_rate_selection.json\').exists()\n            write(\'notes/day17_static_rate_selection.json\', receipt)\n            preserve()  # Freeze the pilot-only choice on GitHub before confirmation.\n            for seed in range(2027, 2032):\n                for order in [\'canonical\', \'b_first\']:\n                    for rank in [8, 96]:\n                        if datetime.now(timezone.utc) >= LAUNCH_CUTOFF:\n                            stopped = True\n                            break\n                        rate = selected[str(rank)]\n                        tag = int(round(rate * 1e6))\n                        run_job(records, f\'day17_confirm_rank{rank}_lr{tag}_seed{seed}_{order}\',\n                                rank, rate, seed, order, \'confirmation\')\n    except Exception as error:\n        failed = True\n        write(\'notes/day17_static_tuning_failure.json\', {\'error\': repr(error), \'utc\': now()})\n        print(\'STATIC_BASELINE_HALTED\', repr(error), flush=True)\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 44, \'github_save_pending\': True,\n                   \'failed\': failed, \'administratively_stopped\': stopped})\n    preserve()\n    receipt = verify_new_checkpoint_roundtrip()\n    complete = sum(r[\'phase\'] != \'replay_gate\' and r[\'status\'] == \'completed\' for r in records) == 44 and not failed\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 44, \'github_save_pending\': False,\n                   \'github_save_verified\': True, \'failed\': failed, \'complete\': complete,\n                   \'administratively_stopped\': stopped})\n    if command([\'git\', \'add\', \'notes/day17_github_save_verification.json\', str(STATUS)]):\n        raise RuntimeError(\'Final baseline receipt staging failed\')\n    if command([\'git\', \'commit\', \'-m\', \'Record verified checkpoint preservation for tuned static baselines\']):\n        raise RuntimeError(\'Final baseline receipt commit failed\')\n    if command([\'git\', \'push\', \'origin\', BRANCH]):\n        raise RuntimeError(\'Final baseline receipt push failed\')\n    head = read([\'git\', \'rev-parse\', \'HEAD\'])\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + BRANCH]).split()[0] == head\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    print(\'STATIC_BASELINE_AND_GITHUB_SAVE_COMPLETE\', head, \'COMPLETE\', complete, \'FAILED\', failed, flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day17_integrate_saved_branches.py': '"""Integrate independent, verified branches without racing research workers."""\nfrom datetime import datetime, timezone\nimport fcntl\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport time\n\nROOT = Path(\'/workspace/mitosis-interference\')\nAUXILIARY = Path(\'/workspace/mitosis-static-tuning\')\nMAIN_BRANCH = \'day5-causal-audit\'\nSTATIC_BRANCH = \'day17-static-tuning-20261006\'\nDEADLINE = datetime.fromisoformat(\'2026-10-07T03:25:00+00:00\')\nENV = os.environ.copy()\nENV.update(GIT_TERMINAL_PROMPT=\'0\', GH_PROMPT_DISABLED=\'1\', TOKENIZERS_PARALLELISM=\'false\')\n\n\ndef now():\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef read(args, cwd=ROOT):\n    return subprocess.check_output(args, cwd=cwd, env=ENV, text=True, timeout=90).strip()\n\n\ndef command(args, log=None):\n    print(\'RUN\', \' \'.join(args), flush=True)\n    return subprocess.run(args, cwd=ROOT, env=ENV, stdin=subprocess.DEVNULL,\n                          stdout=log, stderr=subprocess.STDOUT if log else None).returncode\n\n\ndef write(path, value):\n    Path(path).write_text(json.dumps(value, indent=2) + \'\\n\')\n\n\ndef push(message):\n    assert command([\'git\', \'add\', \'-A\']) == 0\n    if read([\'git\', \'status\', \'--porcelain\']):\n        assert command([\'git\', \'commit\', \'-m\', message]) == 0\n    assert command([\'git\', \'push\', \'origin\', MAIN_BRANCH]) == 0\n    head = read([\'git\', \'rev-parse\', \'HEAD\'])\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + MAIN_BRANCH]).split()[0] == head\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    return head\n\n\ndef main():\n    os.chdir(ROOT)\n    main_lock = open(\'/workspace/mitosis-restart-worker.lock\', \'a\')\n    static_lock = open(\'/workspace/mitosis-static-tuning-worker.lock\', \'a\')\n    while True:\n        if datetime.now(timezone.utc) >= DEADLINE:\n            raise RuntimeError(\'Integration cutoff; retain both independently preserved branches\')\n        acquired = []\n        try:\n            for lock in [main_lock, static_lock]:\n                fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\n                acquired.append(lock)\n            paths = [ROOT / \'notes/day15_16_execution_status.json\',\n                     AUXILIARY / \'notes/day17_static_tuning_execution.json\']\n            if all(p.exists() for p in paths):\n                diagnostic, static = [json.loads(p.read_text()) for p in paths]\n                if diagnostic.get(\'github_save_verified\') and static.get(\'github_save_verified\'):\n                    break\n        except BlockingIOError:\n            pass\n        finally:\n            if len(acquired) != 2 or not (\'diagnostic\' in locals() and \'static\' in locals()\n                    and diagnostic.get(\'github_save_verified\') and static.get(\'github_save_verified\')):\n                for lock in acquired:\n                    fcntl.flock(lock, fcntl.LOCK_UN)\n        print(\'INTEGRATION_WAITING_FOR_BOTH_VERIFIED_SAVES\', now(), flush=True)\n        time.sleep(30)\n    assert read([\'git\', \'branch\', \'--show-current\']) == MAIN_BRANCH\n    assert read([\'git\', \'remote\', \'get-url\', \'origin\']) == \'https://github.com/anitusiruk/mitosis-interference.git\'\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    main_head = read([\'git\', \'rev-parse\', \'HEAD\'])\n    static_head = read([\'git\', \'rev-parse\', \'HEAD\'], AUXILIARY)\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + MAIN_BRANCH]).split()[0] == main_head\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + STATIC_BRANCH]).split()[0] == static_head\n    assert command([\'git\', \'merge\', \'--no-ff\', \'--no-edit\', STATIC_BRANCH]) == 0\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    codes = {}\n    for label, module in [(\'manuscript\', \'experiments.day17_manuscript_refresh\'),\n                          (\'figures\', \'experiments.day17_evidence_figures\')]:\n        with Path(\'logs\', \'day17_integrated_\' + label + \'.txt\').open(\'x\') as log:\n            codes[label] = command([sys.executable, \'-u\', \'-m\', module], log)\n    manifest = {}\n    for p in sorted(Path(\'results\').rglob(\'*\')):\n        if p.is_file() and \'checkpoint\' in p.parts:\n            digest = hashlib.sha256()\n            with p.open(\'rb\') as stream:\n                for block in iter(lambda: stream.read(8 * 1024 * 1024), b\'\'):\n                    digest.update(block)\n            manifest[str(p)] = {\'bytes\': p.stat().st_size, \'sha256\': digest.hexdigest()}\n    write(\'results/checkpoint_preservation_manifest.json\', manifest)\n    preservation = json.loads(Path(\'notes/preservation_status.json\').read_text())\n    preservation.update(checkpoint_files=len(manifest), checkpoint_bytes=sum(r[\'bytes\'] for r in manifest.values()),\n                        new_snapshot_push_pending=True, github_ref_verified=False,\n                        remote_checkpoints_sha256_verified=False)\n    write(\'notes/preservation_status.json\', preservation)\n    integration = {\'utc\': now(), \'diagnostic_branch_head\': main_head, \'static_branch_head\': static_head,\n        \'repository\': \'anitusiruk/mitosis-interference\', \'editorial_returncodes\': codes,\n        \'diagnostic_complete\': diagnostic.get(\'complete\'), \'diagnostic_failed\': diagnostic.get(\'failed\'),\n        \'static_complete\': static.get(\'complete\'), \'static_failed\': static.get(\'failed\'),\n        \'combined_save_pending\': True}\n    write(\'notes/day17_branch_integration.json\', integration)\n    push(\'Integrate preserved static tuning and refresh all diagnostic evidence\')\n    if command([sys.executable, \'-u\', \'-m\', \'experiments.finalize_github_save\']):\n        raise RuntimeError(\'Combined remote checkpoint verification failed; retain local and branch saves\')\n    receipt = json.loads(Path(\'notes/github_save_verification.json\').read_text())\n    assert receipt[\'all_current_lfs_sha256_verified\']\n    preservation.update(github_push_returncode=0, github_ref_verified=True,\n        new_snapshot_push_pending=False, remote_checkpoints_sha256_verified=True,\n        last_successful_github_snapshot_commit=receipt[\'preserved_snapshot_commit\'],\n        last_successful_github_save_verified_utc=receipt[\'verified_utc\'])\n    write(\'notes/preservation_status.json\', preservation)\n    integration.update(combined_save_pending=False, combined_remote_checkpoints_verified=True,\n                       verified_utc=now(), verified_snapshot=receipt[\'preserved_snapshot_commit\'])\n    write(\'notes/day17_branch_integration.json\', integration)\n    head = push(\'Record independently verified combined research checkpoint preservation\')\n    print(\'INTEGRATED_RESEARCH_AND_GITHUB_SAVE_COMPLETE\', head, \'EDITORIAL\', codes, flush=True)\n    if any(codes.values()):\n        raise RuntimeError(\'Editorial discrepancy preserved; inspect the corresponding log\')\n\n\nif __name__ == \'__main__\':\n    main()\n', 'notes/day17_execution_isolation_20261006.md': "# Administrative execution amendment for static-baseline tuning\n\nAt 2026-10-07 01:34 UTC, before any Day-17 replay or tuning outcome, the live\ndiagnostic queue had completed all 20 BERT trajectories and four Day-15 observer\ntrajectories. All four observers passed their exact reference replay. The\nremaining all-mature-batch factorial audits would consume most of the remaining\nevening. The previously staged sequential static queue would therefore risk\nnever starting before the administrative cutoff.\n\nRun the unchanged Day-17 rank/rate protocol in a separate Git worktree, on branch\n`day17-static-tuning-20261006` of the same `anitusiruk/mitosis-interference`\nrepository. This is execution isolation, not a new repository, dataset,\nhyperparameter grid, selection metric, or scientific comparison. Preserve all\n24 pilots, the pilot-only rate-selection receipt before confirmation, and all\n20 planned paired development confirmations. Do not select or reduce coverage\naccording to outcomes. Keep the original replay gate, stream hashes, clipping,\ninitialization, memory budget and training recipe unchanged.\n\nBoth queues share one RTX 4090. A complete bitwise static replay must pass under\nthis execution environment before the first pilot is launched. A failure halts\nthe static queue and preserves the attempted replay. Neither training-time\ncomparisons nor GPU utilization during overlapping work are dedicated compute\nbenchmarks. Timing and peak-memory receipts are descriptive. A passing replay\nchecks this concrete implementation; it is not a proof about all GPU scheduling.\n\nUse separate worktree indexes, output folders and execution locks. The original\nworker continues its unchanged queue and original cutoff. The static worker\ncommits each attempt to its branch, verifies the remote ref, and independently\ndownloads and hashes every newly generated Day-17 LFS checkpoint. It never\nrewrites the main checkout's preservation manifest or existing backup receipts.\nUnrelated old checkpoint files remain Git LFS pointers in the auxiliary worktree;\nthe exact rank-96 replay reference is materialized from already verified objects.\n\nAfter both queues finish and both remote checkpoint receipts pass, merge the\nstatic branch into `day5-causal-audit` without overwriting independent results.\nRefresh the manuscript with actual coverage, including any administrative partial\nDay-15 coverage. Recompute the complete checkpoint manifest and verify the final\ncombined GitHub snapshot. Failed attempts remain part of the record. The\n10:00 PM Dallas launch cutoff, 10:15 PM training deadline and 10:25 PM integration\ntarget remain administrative limits. If integration cannot finish, leave both\nbranches preserved and report the exact remaining step.\n\nThis amendment changes execution scheduling only. The adaptive references and\ndevelopment examples had already been examined before the static study; its\nresults do not become untouched final evaluation through this isolation.\n"}

import ast,datetime,hashlib,json,os,signal,subprocess,sys,time
from pathlib import Path
ROOT=Path('/workspace/mitosis-interference')
TARGET=Path('/workspace/mitosis-static-tuning')
