ENV=os.environ.copy();ENV.update(GIT_TERMINAL_PROMPT='0',GH_PROMPT_DISABLED='1',GIT_LFS_SKIP_SMUDGE='1',OMP_NUM_THREADS='8',TOKENIZERS_PARALLELISM='false')
def read(args,cwd=ROOT):return subprocess.check_output(args,cwd=cwd,env=ENV,text=True,timeout=90).strip()
def run(args,cwd=ROOT):
 print('RUN',' '.join(args),flush=True)
 answer=subprocess.run(args,cwd=cwd,env=ENV,stdin=subprocess.DEVNULL)
 if answer.returncode:raise RuntimeError('Failed command: '+str(args[:4]))
assert not TARGET.exists()
assert read(['git','branch','--show-current'])=='day5-causal-audit'
assert read(['git','remote','get-url','origin'])=='https://github.com/anitusiruk/mitosis-interference.git'
assert read(['gh','api','repos/anitusiruk/mitosis-interference','--jq','.permissions.push'])=='true'
assert not read(['git','branch','--list',BRANCH])
staging=Path('/workspace/mitosis-day15-stage/install_static_followon.py')
assert hashlib.sha256(staging.read_bytes()).hexdigest()=='28d504ba2da84dd06af6d5344b8ab61f2cb44bd28eac231709c4359a721f4230'
tree=ast.parse(staging.read_text());frozen=ast.literal_eval(tree.body[0].value)
