# The old sequential installer has only waited; stop this waiting process, not research.
pid=10594
process=Path('/proc',str(pid),'cmdline')
assert process.exists() and str(staging).encode() in process.read_bytes()
assert not (ROOT/'experiments/day17_static_tuning.py').exists()
assert 'WAITING_FOR_DIAGNOSTICS_AND_VERIFIED_SAVE' in Path('/workspace/mitosis-day15-stage/static_followon.log').read_text()[-300:]
os.kill(pid,signal.SIGTERM)
for i in range(50):
 if not process.exists():break
 time.sleep(.1)
else:raise RuntimeError('Waiting installer did not stop; no competing installation permitted')
print('STOPPED_WAITING_SEQUENTIAL_INSTALLER',pid,flush=True)
base=read(['git','rev-parse','HEAD'])
run(['git','worktree','add','-b',BRANCH,str(TARGET),base])
for name,text in dict(frozen,**ADDITIONS).items():
 p=TARGET/name
 assert not p.exists() and not Path(name).is_absolute() and '..' not in Path(name).parts
 p.write_text(text);print('ISOLATED_SOURCE',name,hashlib.sha256(p.read_bytes()).hexdigest(),flush=True)
# Materialize only the exact replay reference. Other old checkpoints remain pointers.
reference='results/day12_banking_private_single_rank96_seed2031_b_first/checkpoint/'
lines=read(['git','lfs','ls-files','--long'],TARGET).splitlines()
paths=[line.split(' ',2)[2] for line in lines if line.split(' ',2)[2].startswith(reference)]
assert paths
run(['git','lfs','checkout',*paths],TARGET)
for name in paths:
 assert not (TARGET/name).read_bytes().startswith(b'version https://git-lfs.github.com/spec/v1')
run([sys.executable,'-m','compileall','-q',*[str(TARGET/p) for p in dict(frozen,**ADDITIONS) if p.endswith('.py')]],TARGET)
with (TARGET/'logs/day17_static_report_analytic_gate.txt').open('x') as log:
 code=subprocess.run([sys.executable,'-u','-m','experiments.day17_static_report_integrity'],cwd=TARGET,env=ENV,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT).returncode
(TARGET/'notes/day17_prelaunch_gate.json').write_text(json.dumps({'gate_returncode':code,'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'research_outcomes_generated':False,'scope':'compile and analytic selection/report fixtures','execution_isolation':'separate worktree, shared GPU, same existing repository'},indent=2)+'\n')
run(['git','add','-A'],TARGET)
